import { FieldError } from "react-hook-form";
import { useTranslations } from "next-intl";

export type ValidationTranslator = ReturnType<typeof useTranslations>;

/**
 * Maps a React Hook Form FieldError (generated by Zod schemas) to a localized translation message
 * using next-intl useTranslations without `any`.
 */
export const getErrorMessage = (
  error: FieldError | undefined,
  t: ValidationTranslator
): string | undefined => {
  if (!error?.message) {
    return undefined;
  }

  const key = error.message;

  if (key === "minLength") {
    return t("minLength", { min: 8 });
  }

  return t(key);
};
